 * @param event         触发事件：SUBMIT 提交附页 / REVOKE 撤销附页
 * @param status        标记状态：PENDING 待复审
 * @param createdAtUtc  标记生成时刻（UTC）
 */
public record ReviewFlagRecord(
        long flagId,
