                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                entry.observationId(),
                entry.corrVersion(),
                entry.baseVersion(),
                writeDiffs(entry.diffs()),
                entry.reason(),
                entry.collector(),
                entry.corrKey(),
                entry.status(),
                Timestamp.from(entry.createdAtUtc()));
    }

    /**
     * 查询某观测记录的全部附页，按附页版本升序（附页链）。
     */
