/**
 * 查询某观测记录当前最大附页版本号；无附页时返回空。
 */
public Optional<Integer> findMaxCorrVersion(String observationId) {
    return jdbcTemplate.query(
                    "SELECT MAX(corr_version) AS max_version FROM corrigendum WHERE observation_id = ?",
